    "repayConv.confirmRerecordWithExtra": { en: "This entry is a repayment ({friend}): {cur} {total} on loans plus an extra entry of {cur} {extra}. It will be canceled, its extra entry removed, and the one you entered recorded in its place, paying the oldest debts first. Continue?", es: "Este movimiento es un repago ({friend}): {cur} {total} en préstamos más un movimiento extra de {cur} {extra}. Se cancelará, se quitará su movimiento extra y se registrará en su lugar el que ingresaste, pagando primero las deudas más antiguas. ¿Continuar?" },
