    // ---- signin ----
    "link.title": { en: "Connect your app", es: "Conecta tu app" },
    "link.introBrowser": { en: "Go back to the setup page and tap “Copy my access code”. Then come back here and tap the button below.", es: "Vuelve a la página de configuración y toca “Copiar mi código de acceso”. Luego regresa aquí y toca el botón de abajo." },
    "link.installTitle": { en: "Add this app to your Home Screen", es: "Agrega esta app a tu pantalla de inicio" },
    "link.stepCopy": { en: "Tap “Copy my access code” below.", es: "Toca “Copiar mi código de acceso” aquí abajo." },
    "link.stepShare": { en: "Tap the Share button (a square with an arrow pointing up) at the bottom of Safari, then Add to Home Screen, then Add.", es: "Toca el botón Compartir (un cuadrado con una flecha hacia arriba) en la parte de abajo de Safari, luego Agregar a inicio y luego Agregar." },
    "link.stepOpen": { en: "Open the new icon on your Home Screen and tap “Paste my access code”. If your phone asks, tap Allow Paste.", es: "Abre el nuevo ícono de tu pantalla de inicio y toca “Pegar mi código de acceso”. Si tu celular lo pide, toca Permitir pegar." },
    "link.lastStep": { en: "This is the last step. Once you paste your access code in the new icon, you are ready to start using the app.", es: "Este es el último paso. Cuando pegues tu código de acceso en el nuevo ícono, ya podrás empezar a usar la app." },
    "link.copyBtn": { en: "Copy my access code", es: "Copiar mi código de acceso" },
    "link.copied": { en: "✓ Copied. Now add the app to your Home Screen (step 2).", es: "✓ Copiado. Ahora agrega la app a tu pantalla de inicio (paso 2)." },
    "link.copyBlocked": { en: "Your phone did not allow copying. Go back to the setup page and tap “Copy my access code” there.", es: "Tu celular no permitió copiar. Vuelve a la página de configuración y toca “Copiar mi código de acceso” ahí." },
    "link.noHandoff": { en: "No access code found in Safari. Open the setup page and tap “Copy my access code” first, then add the app to your Home Screen.", es: "No se encontró un código de acceso en Safari. Abre la página de configuración y toca “Copiar mi código de acceso” primero; luego agrega la app a tu pantalla de inicio." },
    "link.useSafari": { en: "I only want to use it in Safari", es: "Solo quiero usarla en Safari" },
    "link.introInstalled": { en: "Your access code is waiting on the clipboard, copied by the setup page. Tap the button below. (If it is not there, go back to the setup page and tap “Copy my access code” again.)", es: "Tu código de acceso está esperando en el portapapeles, copiado por la página de configuración. Toca el botón de abajo. (Si no está, vuelve a la página de configuración y toca “Copiar mi código de acceso” otra vez.)" },
    "link.pasteBtn": { en: "Paste my access code", es: "Pegar mi código de acceso" },
    "link.manualSummary": { en: "Paste doesn't work? Do it by hand", es: "¿No funciona pegar? Hazlo a mano" },
    "link.manualHint": { en: "Press and hold in the box, tap Paste, then tap Use this text.", es: "Mantén presionado en el cuadro, toca Pegar y luego toca Usar este texto." },
    "link.useText": { en: "Use this text", es: "Usar este texto" },
    "link.nothing": { en: "Nothing to paste yet. Go back to the setup page, tap “Copy my access code”, then try again.", es: "Aún no hay nada que pegar. Vuelve a la página de configuración, toca “Copiar mi código de acceso” e inténtalo de nuevo." },
    "link.notRight": { en: "That is not an access code from the setup page. Go back to it and tap “Copy my access code”.", es: "Eso no es un código de acceso de la página de configuración. Vuelve a ella y toca “Copiar mi código de acceso”." },
    "link.pasteBlocked": { en: "Your phone did not allow pasting. Use the box below instead.", es: "Tu celular no permitió pegar. Usa el cuadro de abajo." },
    "link.noBackend": { en: "This app is not connected yet.", es: "Esta app aún no está conectada." },
    "signin.intro": { en: "Enter the access code to connect this app to your Google Sheet.", es: "Ingresa el código de acceso para conectar esta app con tu Google Sheet." },
    "signin.placeholder": { en: "Access code", es: "Código de acceso" },
    "signin.connect": { en: "Connect", es: "Conectar" },
    "signin.loading": { en: "Connecting… this can take up to 20 seconds if the app hasn't been used in a while.", es: "Conectando… puede tardar hasta 20 segundos si no has usado la app en los últimos minutos." },
