    "notauto.unread.unreadable": { en: "The app knows this email but couldn't read it — the bank may have changed its wording.", es: "La app conoce este correo pero no pudo leerlo; puede que el banco haya cambiado su formato." },
    "notauto.kind.plin_out_whatsapp": { en: "Plin sent from WhatsApp", es: "Plin enviado desde WhatsApp" },
    "notauto.tip.plin_out_whatsapp": { en: "No email arrives. Send the receipt image to the Telegram bot, or add it by hand.", es: "No llega ningún correo. Envía la imagen del comprobante al bot de Telegram, o agrégalo a mano." },
    "notauto.kind.yape_in": { en: "Yape received", es: "Yape recibido" },
    "notauto.tip.yape_in": { en: "Banks send no email for money you receive. Send the \"¡Te Yapearon!\" screen to the Telegram bot, or add it by hand.", es: "Los bancos no envían correo por el dinero que recibes. Envía la pantalla \"¡Te Yapearon!\" al bot de Telegram, o agrégalo a mano." },
    "notauto.kind.plin_in": { en: "Plin received", es: "Plin recibido" },
