    "notauto.kind.no_email_bank": { en: "Banks the app cannot read yet", es: "Bancos que la app aún no sabe leer" },
    "notauto.tip.no_email_bank": { en: "Entries on accounts of a bank with no email reading. Use More → Bank emails to teach the app your bank, or upload its statements.", es: "Movimientos en cuentas de un banco sin lectura de correos. Usa Más → Correos del banco para enseñarle tu banco a la app, o sube sus estados de cuenta." },
